import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

class ScanError extends Error {
  constructor(pos, reason) { super(reason); this.pos = pos; this.reason = reason }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isLetter = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isAlnum = (c) => isLetter(c) || isDigit(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const out = []
  let i = 0, line = 1, col = 1
  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const here = () => ({ line, col })
  const push = (p, kind, body) => out.push({ p, kind, body })

  // consume a digit run with single underscores between digits
  const run = (isD) => {
    let s = ''
    if (!isD(cs[i])) return s
    while (i < n) {
      if (isD(cs[i])) s += adv()
      else if (cs[i] === '_' && isD(cs[i - 1]) && isD(cs[i + 1])) s += adv()
      else break
    }
    return s
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const p = here()
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(p, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let s = ''
      while (i < n && cs[i] !== '"') s += adv()
      if (i >= n) throw new ScanError(p, 'unterminated string')
      adv()
      push(p, 'rawstring', JSON.stringify(s))
      continue
    }
    if (isLetter(c)) {
      let s = ''
      while (i < n && isAlnum(cs[i])) s += adv()
      push(p, KEYWORDS.has(s) ? 'keyword' : 'ident', s)
      continue
    }
    if (isDigit(c)) {
      let s = ''
      let ok = true
      const nx = cs[i + 1]
      const radix = c === '0' ? { x: isHex, X: isHex, b: (d) => d === '0' || d === '1', B: (d) => d === '0' || d === '1', o: (d) => d >= '0' && d <= '7' && d.length === 1, O: (d) => d >= '0' && d <= '7' && d.length === 1 }[nx] : undefined
      if (radix) {
        s += adv(); s += adv()
        const d = run(radix)
        if (!d) ok = false
        s += d
      } else {
        s += run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { s += adv(); s += run(isDigit) }
        if ((cs[i] === 'e' || cs[i] === 'E') &&
          (isDigit(cs[i + 1]) || ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])))) {
          s += adv()
          if (!isDigit(cs[i])) s += adv()
          s += run(isDigit)
        }
      }
      if (!ok || isAlnum(cs[i])) {
        while (i < n && isAlnum(cs[i])) s += adv()
        throw new ScanError(p, 'invalid number ' + s)
      }
      push(p, 'number', s)
      continue
    }
    if (c === '"') {
      adv()
      let s = ''
      for (;;) {
        if (i >= n) throw new ScanError(p, 'unterminated string')
        const d = cs[i]
        if (d === '\n') throw new ScanError(here(), 'newline in string')
        if (d === '"') { adv(); break }
        if (d !== '\\') { s += adv(); continue }
        const bp = here()
        adv()
        if (i >= n) throw new ScanError(p, 'unterminated string')
        const e = cs[i]
        const bad = () => new ScanError(bp, 'invalid escape \\' + e)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (e in simple) { adv(); s += simple[e] }
        else if (e === 'x') {
          if (!(isHex(cs[i + 1]) && isHex(cs[i + 2]))) throw bad()
          adv(); const h = adv() + adv()
          s += String.fromCodePoint(parseInt(h, 16))
        } else if (e === 'u') {
          if (cs[i + 1] !== '{') throw bad()
          let j = i + 2, h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}' || parseInt(h, 16) > 0x10ffff) throw bad()
          while (i <= j) adv()
          s += String.fromCodePoint(parseInt(h, 16))
        } else throw bad()
      }
      push(p, 'string', JSON.stringify(s))
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.has(two)) { adv(); adv(); push(p, 'punct', two); continue }
    if (PUNCT1.has(c)) { adv(); push(p, 'punct', c); continue }
    throw new ScanError(p, 'unexpected character ' + c)
  }
  return out
}

let toks
try {
  toks = scan(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.pos.line}:${e.pos.col}: ${e.reason}\n`)
  process.exit(2)
}
let res = ''
if (mode === 'tokens') {
  for (const t of toks) res += `${t.p.line}:${t.p.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
    res += `${k} ${toks.filter((t) => t.kind === k).length}\n`
  }
  res += `total ${toks.length}\n`
}
process.stdout.write(res)
EOF
