{"file_path":"src/cli.js","content":"import fs from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const fail = (msg) => {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

// ---------- addresses ----------
function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
}
function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}
// returns {col,row} or null
function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colIndex(m[1].toUpperCase()), row }
}
const keyOf = (col, row) => col * 1000 + row
const nameOf = (col, row) => colName(col) + row

// ---------- parse sheet ----------
const input = fs.readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map() // key -> {col,row,content}
lines.forEach((raw, idx) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  let i = 0
  while (i < line.length && line[i] !== ' ' && line[i] !== '\t') i++
  const addrText = line.slice(0, i)
  while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
  const content = line.slice(i)
  const a = parseAddr(addrText)
  if (!a) fail(`error: line ${idx + 1}: invalid cell address ${addrText}`)
  const key = keyOf(a.col, a.row)
  if (cells.has(key)) fail(`error: line ${idx + 1}: cell ${nameOf(a.col, a.row)} is declared twice`)
  cells.set(key, { col: a.col, row: a.row, content })
})
const order = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)

// ---------- lexer / parser ----------
class GrammarError extends Error {}

function lex(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^\d+(\.\d+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    const two = src.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { toks.push({ t: 'op', v: two }); i += 2; continue }
    if ('^*/+-=<>(),:'.includes(c)) { toks.push({ t: 'op', v: c }); i++; continue }
    throw new GrammarError()
  }
  return toks
}

function parseFormula(body) {
  const toks = lex(body)
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const expect = (v) => { if (!isOp(v)) throw new GrammarError(); p++ }

  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
