const err = (v) => ({ t: 'e', v })
const ERR = err('#ERR!'), REF = err('#REF!'), VALUE = err('#VALUE!'), DIV = err('#DIV/0!'),
  CYCLE = err('#CYCLE!'), NAME = err('#NAME?')
const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

function finite(x) { return Number.isFinite(x) ? num(x) : DIV }

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 'e') return v
  return VALUE
}

function cpCompare(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0)), y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}
const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] < rank[b.t] ? -1 : 1
  if (a.t === 's') return cpCompare(a.v, b.v)
  const x = a.t === 'b' ? +a.v : a.v, y = b.t === 'b' ? +b.v : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

const memo = new Map()
const busy = new Set()
const parsed = new Map()

function cellValue(key) {
  if (memo.has(key)) return memo.get(key)
  const cell = cells.get(key)
  if (!cell) return num(0)
  if (busy.has(key)) return CYCLE
  busy.add(key)
  let v
  try { v = evalContent(cell, key) } finally { busy.delete(key) }
  memo.set(key, v)
  return v
}

function getAst(key) {
  if (parsed.has(key)) return parsed.get(key)
  let r
  try {
    const ast = parseFormula(cells.get(key).content.slice(1))
    r = { ast, bad: misplaced(ast) }
  } catch (e) {
    if (!(e instanceof GrammarError)) throw e
    r = null
  }
  parsed.set(key, r)
  return r
}

function evalContent(cell, key) {
  const c = cell.content
  if (c[0] === '=') {
    const r = getAst(key)
    if (!r || r.bad) return ERR
    return ev(r.ast)
  }
  if (c === '') return num(0)
  if (/^-?\d+(\.\d+)?$/.test(c)) return num(Number(c))
  if (ERROR_TOKENS.has(c)) return err(c)
  return { t: 's', v: c }
}

function refValue(w) {
  const a = parseAddr(w)
  if (!a) return REF
  return cellValue(keyOf(a.col, a.row))
}

function rangeValues(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return [REF]
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(cellValue(keyOf(c, r)))
  return out
}

function ev(n) {
  switch (n.type) {
    case 'num': return num(n.v)
    case 'bool': return { t: 'b', v: n.v }
    case 'paren': return ev(n.e)
    case 'ref': return refValue(n.w)
    case 'range': return ERR
    case 'un': {
      const x = toNum(ev(n.e))
      if (x.t === 'e') return x
      return num(n.op === '-' ? -x.v : x.v)
    }
    case 'bin': return evBin(n)
    case 'call': return evCall(n)
  }
  return ERR
}

function evBin(n) {
  const l = ev(n.l)
  const r = ev(n.r)
  if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
    if (l.t === 'e') return l
    if (r.t === 'e') return r
    const c = compare(l, r)
    const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
    return { t: 'b', v: res }
  }
  const x = toNum(l)
  if (x.t === 'e') return x
  const y = toNum(r)
  if (y.t === 'e') return y
  switch (n.op) {
    case '+': return finite(x.v + y.v)
    case '-': return finite(x.v - y.v)
    case '*': return finite(x.v * y.v)
    case '/': return y.v === 0 ? DIV : finite(x.v / y.v)
    case '^': return finite(Math.pow(x.v, y.v))
  }
  return ERR
}

const FUNCS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

function evCall(n) {
  const name = n.name
  if (!FUNCS.has(name)) return NAME
  const k = n.args.length
  if (name === 'IF') {
    if (k !== 3) return ERR
    const c = ev(n.args[0])
    if (c.t === 'e') return c
    let truth
    if (c.t === 'b') truth = c.v
    else if (c.t === 'n') truth = c.v !== 0
    else return VALUE
    return ev(n.args[truth ? 1 : 2])
  }
  if (name === 'ABS') {
    if (k !== 1) return ERR
    const x = toNum(ev(n.args[0]))
    if (x.t === 'e') return x
    return num(Math.abs(x.v))
  }
  if (k < 1) return ERR
  const vals = []
  for (const a of n.args) {
    if (a.type === 'range') vals.push(...rangeValues(a))
    else vals.push(ev(a))
  }
  const firstErr = vals.find((v) => v.t === 'e')
  if (firstErr) return firstErr
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
    case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    case 'MIN': return num(nums.reduce((s, x) => (x < s ? x : s), nums[0]))
    case 'MAX': return num(nums.reduce((s, x) => (x > s ? x : s), nums[0]))
  }
  return ERR
}

function show(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

// ---------- output ----------
const out = []
for (const cell of order) {
  const key = keyOf(cell.col, cell.row)
  const name = nameOf(cell.col, cell.row)
  if (mode === 'values') {
    out.push(`${name}=${show(cellValue(key))}`)
  } else {
    let line = `${name}:`
    if (cell.content[0] === '=') {
      const r = getAst(key)
      if (r) {
        const set = new Set()
        collectDeps(r.ast, set)
        const keys = [...set].sort((a, b) => a - b)
        for (const k of keys) line += ' ' + nameOf(Math.floor(k / 1000), k % 1000)
      }
    }
    out.push(line)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
"}

