import { readFileSync } from 'node:fs'

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const newTable = () => ({ t: 'table', m: new Map(), explicit: false })
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const join = (p, k) => (p === '' ? k : p + '.' + k)

function parseLine(s) {
  let i = 0
  const skipWs = () => { while (i < s.length && isWs(s[i])) i++ }
  // skip whitespace; a comment character ends the line
  const skip = () => {
    skipWs()
    if (s[i] === '#' || s[i] === ';') i = s.length
  }
  const atEnd = () => i >= s.length

  function parseString() {
    const q = s[i++]
    let out = ''
    if (q === "'") {
      const e = s.indexOf("'", i)
      if (e < 0) fail('unterminated string')
      out = s.slice(i, e)
      i = e + 1
      return out
    }
    for (;;) {
      if (i >= s.length) fail('unterminated string')
      const c = s[i++]
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      if (i >= s.length) fail('unterminated string')
      const e = s[i++]
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = s.slice(i, i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        i += 4
      } else fail('invalid escape \\' + e)
    }
  }

  function parseName() {
    const c = s[i]
    if (c === '"' || c === "'") return parseString()
    if (!isNameChar(c)) fail('expected a name')
    const st = i
    while (isNameChar(s[i])) i++
    return s.slice(st, i)
  }

  function parseDotted() {
    const names = [parseName()]
    for (;;) {
      const save = i
      skipWs()
      if (s[i] === '.') {
        i++
        skipWs()
        names.push(parseName())
      } else { i = save; return names }
    }
  }

  function parseValue() {
    const c = s[i]
    if (c === '"' || c === "'") return { t: 'string', v: parseString() }
    if (c === '[') {
      i++
      const items = []
      for (;;) {
        skip()
        if (atEnd()) fail('unterminated array')
        if (s[i] === ']') { i++; return { t: 'array', items } }
        items.push(parseValue())
        skip()
        if (atEnd()) fail('unterminated array')
        if (s[i] === ',') { i++; continue }
        if (s[i] === ']') { i++; return { t: 'array', items } }
        fail('unterminated array')
      }
    }
    if (c === '{') {
      i++
      const pairs = []
      skip()
      if (atEnd()) fail('unterminated inline table')
      if (s[i] === '}') { i++; return { t: 'inline', pairs } }
      for (;;) {
        skip()
        if (atEnd()) fail('unterminated inline table')
        const names = parseDotted()
        skipWs()
        if (s[i] !== '=') fail('expected = in an inline table')
        i++
        skip()
        const v = parseValue()
        pairs.push([names, v])
        skip()
        if (atEnd()) fail('unterminated inline table')
        if (s[i] === ',') { i++; continue }
        if (s[i] === '}') { i++; return { t: 'inline', pairs } }
        fail('unterminated inline table')
      }
    }
    const st = i
    while (i < s.length && !isWs(s[i]) && !',]};'.includes(s[i])) i++
    const w = s.slice(st, i)
    if (w === '') fail('expected a value')
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    const num = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${num}$`).test(w)) {
      return { t: 'integer', v: BigInt(w.replace(/_/g, '')).toString() }
    }
    if (new RegExp(`^[+-]?${num}(?:\\.${num}(?:[eE][+-]?${num})?|[eE][+-]?${num})$`).test(w)) {
      return { t: 'float', v: Number(w.replace(/_/g, '')) }
    }
    fail('invalid value ' + w)
  }

  skipWs()
  if (atEnd() || s[i] === '#' || s[i] === ';') return null

  if (s[i] === '[') {
    i++
    const aot = s[i] === '['
    if (aot) i++
    skipWs()
    if (atEnd()) fail('unterminated table header')
    const names = parseDotted()
    skipWs()
    if (s[i] !== ']') fail('unterminated table header')
    i++
    if (aot) {
      if (s[i] !== ']') fail('unterminated table header')
      i++
    }
    skip()
    if (!atEnd()) fail('trailing text after a table header')
    return { kind: aot ? 'aot' : 'table', names }
  }

  const names = parseDotted()
  skipWs()
  if (s[i] !== '=') fail('expected key = value')
  i++
  skip()
  const value = parseValue()
  skip()
  if (!atEnd()) fail('trailing text after a value')
  return { kind: 'kv', names, value }
}

// walk through all but the last name, creating tables
function walk(table, path, names) {
  for (let k = 0; k < names.length - 1; k++) {
    const n = names[k]
    path = join(path, n)
    let c = table.m.get(n)
    if (!c) { c = newTable(); table.m.set(n, c) }
    if (c.t === 'table') table = c
    else if (c.t === 'array' && c.aot) {
      table = c.items[c.items.length - 1]
      path += `[${c.items.length - 1}]`
    } else fail(path + ' is not a table')
  }
  return [table, path]
}

function build(v, path) {
  if (v.t === 'array') {
    return { t: 'array', aot: false, items: v.items.map((x, k) => build(x, `${path}[${k}]`)) }
  }
  if (v.t === 'inline') {
    const tb = newTable()
    for (const [names, val] of v.pairs) assign(tb, path, names, val)
    return tb
  }
  return v
}

function assign(table, path, names, val) {
  const [t, p] = walk(table, path, names)
  const last = names[names.length - 1]
  const full = join(p, last)
  if (t.m.has(last)) fail(`key ${full} is defined twice`)
  t.m.set(last, build(val, full))
}

function parseDoc(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = ''
  lines.forEach((line, idx) => {
    try {
      const r = parseLine(line)
      if (!r) return
      if (r.kind === 'kv') {
        assign(cur, curPath, r.names, r.value)
      } else if (r.kind === 'table') {
        const [t, p] = walk(root, '', r.names)
        const last = r.names[r.names.length - 1]
        const full = join(p, last)
        let c = t.m.get(last)
        if (!c) { c = newTable(); t.m.set(last, c) }
        if (c.t !== 'table') fail(full + ' is not a table')
        if (c.explicit) fail(`table ${full} is defined twice`)
        c.explicit = true
        cur = c
        curPath = full
      } else {
        const [t, p] = walk(root, '', r.names)
        const last = r.names[r.names.length - 1]
        const full = join(p, last)
        let c = t.m.get(last)
        if (!c) { c = { t: 'array', aot: true, items: [] }; t.m.set(last, c) }
        if (c.t !== 'array' || !c.aot) fail(full + ' is not an array of tables')
        const nt = newTable()
        nt.explicit = true
        c.items.push(nt)
        cur = nt
        curPath = `${full}[${c.items.length - 1}]`
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${idx + 1}: ${e.message}`)
      throw e
    }
  })
  return root
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let k = 0; k < Math.min(x.length, y.length); k++) if (x[k] !== y[k]) return x[k] - y[k]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(n.m.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (n.t === 'integer') return n.v
  return JSON.stringify(n.v)
}

function toKeys(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n)) {
      const c = n.m.get(k)
      const p = join(path, k)
      out.push(`${p} ${c.t}`)
      toKeys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, k) => {
      const p = `${path}[${k}]`
      out.push(`${p} ${c.t}`)
      toKeys(c, p, out)
    })
  }
}

try {
  const root = parseDoc(readFileSync(0, 'utf8'))
  if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
  else {
    const out = []
    toKeys(root, '', out)
    process.stdout.write(out.map((l) => l + '\n').join(''))
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
