if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let names = null
const known = new Set()
const ballots = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (names !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    names = []
    for (const nm of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(nm)) fail(`error: line ${n}: invalid candidate name ${nm}`)
      if (known.has(nm)) fail(`error: line ${n}: candidate ${nm} is declared twice`)
      known.add(nm)
      names.push(nm)
    }
  } else if (t[0] === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const nm of t.slice(2)) {
      if (!known.has(nm)) fail(`error: line ${n}: unknown candidate ${nm}`)
      if (seen.has(nm)) fail(`error: line ${n}: candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
}
if (names === null) fail('error: no candidates')

const continuing = new Set(names)
const history = new Map(names.map((c) => [c, []]))
const out = []
let roundNo = 0
let result
for (;;) {
  roundNo++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  let total = 0n
  for (const b of ballots) {
    total += b.count
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  for (const [c, v] of counts) history.get(c).push(v)
  const listed = [...counts].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  out.push(`round ${roundNo}: ${listed.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) { result = 'no winner'; break }
  const win = listed.find(([, v]) => v * 2n > active)
  if (win) { result = `winner ${win[0]}`; break }
  let min = listed[0][1]
  for (const [, v] of listed) if (v < min) min = v
  let tied = listed.filter(([, v]) => v === min).map(([c]) => c)
  while (tied.length > 1) {
    let r = 0
    for (; r < roundNo; r++) {
      const vs = tied.map((c) => history.get(c)[r])
      if (vs.some((v) => v !== vs[0])) {
        let m = vs[0]
        for (const v of vs) if (v < m) m = v
        tied = tied.filter((c) => history.get(c)[r] === m)
        break
      }
    }
    if (r === roundNo) {
      tied = [tied.reduce((a, b) => (b > a ? b : a))]
    }
  }
  continuing.delete(tied[0])
  out.push(`eliminated ${tied[0]}`)
}
out.push(result)
if (mode === 'tally') process.stdout.write(`rounds ${roundNo}\n${result}\n`)
else process.stdout.write(out.join('\n') + '\n')
