{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9A-Fa-f]$/.test(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0, line = 1, col = 1
  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  while (i < n) {
    const c = cs[i]
    const sl = line, sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && cs[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdPart(cs[i])) s += adv()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const run = (ok) => {
        // digits with single underscores between digits
        let got = false
        while (i < n && ok(cs[i])) {
          s += adv(); got = true
          while (cs[i] === '_' && ok(cs[i + 1])) { s += adv(); s += adv() }
        }
        return got
      }
      let bad = false
      const p = cs[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        s += adv(); s += adv()
        const lp = p.toLowerCase()
        const ok = lp === 'x' ? isHex : lp === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        if (!run(ok)) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { s += adv(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          const a = cs[i + 1], b = cs[i + 2]
          if (isDigit(a) || ((a === '+' || a === '-') && isDigit(b))) {
            s += adv()
            if (!isDigit(cs[i])) s += adv()
            run(isDigit)
          }
        }
      }
      if (i < n && isIdPart(cs[i])) bad = true
      if (bad) {
        while (i < n && isIdPart(cs[i])) s += adv()
        throw new ScanError(sl, sc, 'invalid number ' + s)
      }
      tokens.push({ line: sl, col: sc, kind: 'number', body: s })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = cs[i]
        if (d === '"') { adv(); break }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') { v += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(bl, bc, 'invalid escape \\' + e)
        if (e === 'n') v += '\n'
        else if (e === 't') v += '\t'
        else if (e === 'r') v += '\r'
        else if (e === '\\') v += '\\'
        else if (e === '"') v += '"'
        else if (e === '0') v += '\0'
        else if (e === 'x') {
          if (!(isHex(cs[i]) && isHex(cs[i + 1]))) throw bad()
          v += String.fromCharCode(parseInt(cs[i] + cs[i + 1], 16))
          adv(); adv()
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1, h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}') throw bad()
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) throw bad()
          while (i <= j) adv()
          v += String.fromCodePoint(cp)
        } else throw bad()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    const p = PUNCT.find((x) => x === two) ?? PUNCT.find((x) => x === c)
    if (p) {
      for (let k = 0; k < p.length; k++) adv()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: p })
      continue
    }
    throw new ScanError(sl, sc, 'unexpected character ' + c)
  }
  return tokens
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  let tokens
  try {
    tokens = scan(readFileSync(0, 'utf8'))
  } catch (e) {
    if (!(e instanceof ScanError)) throw e
    process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
}

main()
