export function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    const end = e < 0 ? s.length : e + 2
    r.authority = s.slice(2, end)
    s = s.slice(end)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

export function splitAuthority(a) {
  let userinfo, rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const rb = rest.lastIndexOf(']')
  const c = rest.indexOf(':', rb < 0 ? 0 : rb)
  let host = rest, port
  if (c >= 0) { host = rest.slice(0, c); port = rest.slice(c + 1) }
  return { userinfo, host, port }
}

export function removeDots(p) {
  let out = ''
  while (p.length) {
    if (p.startsWith('../')) p = p.slice(3)
    else if (p.startsWith('./')) p = p.slice(2)
    else if (p.startsWith('/./')) p = p.slice(2)
    else if (p === '/.') p = '/'
    else if (p.startsWith('/../') || p === '/..') {
      p = p === '/..' ? '/' : p.slice(3)
      out = out.slice(0, Math.max(out.lastIndexOf('/'), 0))
    } else if (p === '.' || p === '..') p = ''
    else {
      const i = p.indexOf('/', 1)
      const seg = i < 0 ? p : p.slice(0, i)
      out += seg
      p = p.slice(seg.length)
    }
  }
  return out
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
export function normPct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}

const asciiLower = s => s.replace(/[A-Z]/g, c => c.toLowerCase())
const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function checkPct(r) {
  const bad = s => s !== undefined && /%(?![0-9A-Fa-f]{2})/.test(s)
  const parts = [['path', r.path]]
  if (r.authority !== undefined) {
    const a = splitAuthority(r.authority)
    parts.push(['userinfo', a.userinfo], ['host', a.host])
  }
  parts.push(['query', r.query], ['fragment', r.fragment])
  for (const [name, v] of parts) if (bad(v)) return name
  return null
}

export function normalize(r) {
  const scheme = r.scheme === undefined ? undefined : asciiLower(r.scheme)
  let authority
  if (r.authority !== undefined) {
    const a = splitAuthority(r.authority)
    authority = ''
    if (a.userinfo !== undefined) authority += normPct(a.userinfo) + '@'
    authority += asciiLower(normPct(a.host))
    if (a.port !== undefined && a.port !== '' && !(scheme !== undefined && DEFAULT_PORT[scheme] === a.port)) {
      authority += ':' + normPct(a.port)
    }
  }
  let path = removeDots(normPct(r.path))
  if (authority !== undefined && path === '') path = '/'
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (authority !== undefined) out += '//' + authority
  out += path
  if (r.query !== undefined) out += '?' + normPct(r.query)
  if (r.fragment !== undefined) out += '#' + normPct(r.fragment)
  return out
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref)
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    t.fragment = ref.fragment
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      t.query = ref.query
      if (ref.path.startsWith('/')) t.path = ref.path
      else if (base.authority !== undefined && base.path === '') t.path = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        t.path = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
      }
    }
  }
  return t
}
