const byCodePoint = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const tally = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const pick = b.prefs.find((p) => continuing.has(p))
      if (pick !== undefined) {
        tally.set(pick, tally.get(pick) + b.count)
        active += b.count
      }
    }
    for (const [c, v] of tally) history.get(c).push(v)
    const lines = [...tally].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : byCodePoint(a[0], b[0])))
    const round = { lines, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    const top = lines.find(([, v]) => v * 2n > active)
    if (top) return { rounds, winner: top[0] }
    let min = null
    for (const [, v] of lines) if (min === null || v < min) min = v
    let set = lines.filter(([, v]) => v === min).map(([c]) => c)
    let r = 0
    while (set.length > 1 && r < rounds.length) {
      let m = null
      for (const c of set) { const v = history.get(c)[r]; if (m === null || v < m) m = v }
      const next = set.filter((c) => history.get(c)[r] === m)
      if (next.length < set.length) { set = next; r = 0 } else r++
    }
    const out = set.sort(byCodePoint).pop()
    round.eliminated = out
    continuing.delete(out)
  }
}
