{"file_path":"src/parse.js","content":"export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const WORD = /^[A-Za-z0-9_.\/:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

function count(line, field, text, least) {
  if (!COUNT.test(text) || BigInt(text) < least) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null

  lines.forEach((raw, i) => {
    const n = i + 1
    const s = raw.trim()
    if (s === '' || s.startsWith('#')) return
    const f = s.split(/\s+/)
    const fail = (m) => { throw new ParseError(n, m) }
    const early = () => { if (events.length) fail('declarations must come before the first event') }
    switch (f[0]) {
      case 'bucket': {
        if (f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        if (!WORD.test(f[1])) fail(`invalid policy name ${f[1]}`)
        const capacity = count(n, 'capacity', f[2], 1n)
        const refill = count(n, 'refill', f[3], 0n)
        const per = count(n, 'per', f[4], 1n)
        early()
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { kind: 'bucket', name: f[1], capacity, refill, per })
        break
      }
      case 'window': {
        if (f.length !== 4) fail('expected window <name> <limit> <span>')
        if (!WORD.test(f[1])) fail(`invalid policy name ${f[1]}`)
        const limit = count(n, 'limit', f[2], 0n)
        const span = count(n, 'span', f[3], 1n)
        early()
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { kind: 'window', name: f[1], limit, span })
        break
      }
      case 'route': {
        if (f.length < 3) fail('expected route <prefix> <policy>...')
        if (!WORD.test(f[1])) fail(`invalid route prefix ${f[1]}`)
        for (const p of f.slice(2)) if (!WORD.test(p)) fail(`invalid policy name ${p}`)
        early()
        if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
        for (const p of f.slice(2)) if (!policies.has(p)) fail(`unknown policy ${p}`)
        routes.set(f[1], f.slice(2).map((p) => policies.get(p)))
        break
      }
      case 'event': {
        if (f.length !== 3) fail('expected event <tick> <key>')
        const tick = count(n, 'tick', f[1], 0n)
        if (!WORD.test(f[2])) fail(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: f[2] })
        break
      }
      default:
        fail(`unknown directive ${f[0]}`)
    }
  })
  return { routes, events }
}
"}

{"file_path":"src/sim.js","content":"// Bucket tokens are stored scaled by `per`, so refill is exact integer math.
function fresh(p, tick) {
  return p.kind === 'bucket'
    ? { units: p.capacity * p.per, last: tick }
    : { ticks: [] }
}

function advance(p, st, tick) {
  if (p.kind === 'bucket') {
    st.units += p.refill * (tick - st.last)
    st.last = tick
    const cap = p.capacity * p.per
    if (st.units > cap) st.units = cap
  } else {
    const cut = tick - p.span
    st.ticks = st.ticks.filter((t) => t > cut)
  }
}

function allows(p, st) {
  return p.kind === 'bucket' ? st.units >= p.per : BigInt(st.ticks.length) < p.limit
}

function record(p, st, tick) {
  if (p.kind === 'bucket') st.units -= p.per
  else st.ticks.push(tick)
}

export function simulate({ routes, events }, mode) {
  const prefixes = [...routes.keys()]
  const states = new Map()
  const stats = new Map()
  const lines = []
  let allowed = 0
  let denied = 0

  for (const { tick, key } of events) {
    let best = null
    for (const pre of prefixes) {
      if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    }
    let refused = null
    if (best !== null) {
      const route = routes.get(best)
      const sts = route.map((p) => {
        const id = `${p.name}\0${key}`
        if (!states.has(id)) states.set(id, fresh(p, tick))
        return states.get(id)
      })
      route.forEach((p, i) => advance(p, sts[i], tick))
      const idx = route.findIndex((p, i) => !allows(p, sts[i]))
      if (idx >= 0) refused = route[idx].name
      else route.forEach((p, i) => record(p, sts[i], tick))
    }
    const s = stats.get(key) ?? { a: 0, d: 0 }
    stats.set(key, s)
    if (refused === null) { s.a++; allowed++ } else { s.d++; denied++ }
    lines.push(refused === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${refused}`)
  }

  if (mode === 'replay') return lines.map((l) => l + '\n').join('')
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  return keys.map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`).join('') +
    `total allowed=${allowed} denied=${denied}\n`
}
"}

