import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function count(field, s, least) {
  if (!UINT.test(s) || BigInt(s) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let last = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    try {
      const t = line.split(/\s+/)
      const d = t[0]
      const decl = d === 'bucket' || d === 'window' || d === 'route'
      if (!decl && d !== 'event') throw new Fail(`unknown directive ${d}`)
      if (d === 'bucket') {
        if (t.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
      } else if (d === 'window') {
        if (t.length !== 4) throw new Fail('expected window <name> <limit> <span>')
      } else if (d === 'route') {
        if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
      } else if (t.length !== 3) throw new Fail('expected event <tick> <key>')
      if (decl && events.length) throw new Fail('declarations must come before the first event')
      if (d === 'bucket' || d === 'window') {
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        let p
        if (d === 'bucket') {
          const capacity = count('capacity', t[2], 1)
          const refill = count('refill', t[3], 0)
          const per = count('per', t[4], 1)
          p = { type: 'bucket', name: t[1], capacity, refill, per }
        } else {
          p = { type: 'window', name: t[1], limit: count('limit', t[2], 0), span: count('span', t[3], 1) }
        }
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], p)
      } else if (d === 'route') {
        if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
        for (const n of t.slice(2)) if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
        routes.set(t[1], t.slice(2).map((n) => policies.get(n)))
      } else {
        const tick = count('tick', t[1], 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (last !== null && tick < last) throw new Fail(`tick ${tick} is before tick ${last}`)
        last = tick
        events.push({ tick, key: t[2] })
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
  return { routes, events }
}

function advance(p, s, tick) {
  if (p.type === 'bucket') {
    if (s.last === undefined) { s.tokens = p.capacity * p.per; s.last = tick; return }
    s.tokens += p.refill * (tick - s.last)
    const cap = p.capacity * p.per
    if (s.tokens > cap) s.tokens = cap
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((x) => x > cut)
  }
}
const allows = (p, s) => (p.type === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit)
function record(p, s, tick) {
  if (p.type === 'bucket') s.tokens -= p.per
  else s.ticks.push(tick)
}

let result
try {
  result = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}

const { routes, events } = result
const prefixes = [...routes.keys()].sort((a, b) => b.length - a.length)
const states = new Map()
const stateOf = (p, key) => {
  const id = p.name + '\0' + key
  let s = states.get(id)
  if (!s) { s = p.type === 'window' ? { ticks: [] } : {}; states.set(id, s) }
  return s
}
const out = []
const per = new Map()
let A = 0, D = 0
for (const { tick, key } of events) {
  const prefix = prefixes.find((x) => key.startsWith(x))
  let denier = null
  if (prefix !== undefined) {
    const ps = routes.get(prefix)
    for (const p of ps) advance(p, stateOf(p, key), tick)
    denier = ps.find((p) => !allows(p, stateOf(p, key))) ?? null
    if (!denier) for (const p of ps) record(p, stateOf(p, key), tick)
  }
  const c = per.get(key) ?? { a: 0, d: 0 }
  per.set(key, c)
  if (denier) { c.d++; D++ } else { c.a++; A++ }
  out.push(denier ? `${tick} ${key} deny ${denier.name}` : `${tick} ${key} allow`)
}
if (mode === 'replay') {
  process.stdout.write(out.map((l) => l + '\n').join(''))
} else {
  const keys = [...per.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let s = ''
  for (const k of keys) s += `${k} allowed=${per.get(k).a} denied=${per.get(k).d}\n`
  process.stdout.write(s + `total allowed=${A} denied=${D}\n`)
}
EOF
