{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const fail = (msg, code = 2) => {
  process.stderr.write(msg + '\n')
  process.exit(code)
}
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

const args = process.argv.slice(2)
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
let mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail(USAGE)
} else if (mode === 'pack') {
  if (args.length !== 2) fail(USAGE)
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const depLines = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
}

const deps = new Map([...cost.keys()].map((k) => [k, new Set()]))
for (const names of depLines) {
  for (const x of names) if (!cost.has(x)) fail(`error: unknown task ${x}`)
  for (const d of names.slice(1)) deps.get(names[0]).add(d)
}
const names = [...cost.keys()].sort(cmp)
const sdeps = new Map(names.map((k) => [k, [...deps.get(k)].sort(cmp)]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const v of sdeps.get(u)) {
    const s = state.get(v)
    if (s === 1) {
      const cyc = stack.slice(stack.indexOf(v)).concat(v)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!s) dfs(v)
  }
  stack.pop()
  state.set(u, 2)
}
for (const k of names) if (!state.get(k)) dfs(k)

const start = new Map()
const finish = new Map()
const depth = new Map()
function calc(u) {
  if (finish.has(u)) return
  let s = 0
  let d = 0
  for (const v of sdeps.get(u)) {
    calc(v)
    s = Math.max(s, finish.get(v))
    d = Math.max(d, depth.get(v) + 1)
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, d)
}
// iterative-safe enough: recursion depth equals chain length
for (const k of names) calc(k)
const total = names.reduce((m, k) => Math.max(m, finish.get(k)), 0)

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ||= []).push(k)
  ws.forEach((g, i) => (out += `wave ${i}: ${g.join(' ')}\n`))
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const rev = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of sdeps.get(k)) rev.get(d).push(k)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0
    for (const v of rev.get(u)) m = Math.max(m, pr(v))
    prio.set(u, m + cost.get(u))
    return m + cost.get(u)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => prio.get(b) - prio.get(a) || cmp(a, b))
  const busy = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  const pf = new Map()
  const pending = new Set(order)
  let t = 0
  let makespan = 0
  while (pending.size) {
    for (;;) {
      const w = busy.findIndex((b) => b <= t)
      if (w < 0) break
      const task = order.find((k) => pending.has(k) && sdeps.get(k).every((d) => pf.has(d) && pf.get(d) <= t))
      if (!task) break
      pending.delete(task)
      const f = t + cost.get(task)
      pf.set(task, f)
      busy[w] = f
      runs[w].push(` ${task}@${t}-${f}`)
      makespan = Math.max(makespan, f)
    }
    if (!pending.size) break
    const next = busy.filter((b) => b > t)
    if (!next.length) break
    t = Math.min(...next)
  }
  runs.forEach((r, i) => (out += `worker ${i}:${r.join('')}\n`))
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
