    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw bad
    const tk = toks[p++]
    if (tk.t === 'num') return { t: 'num', v: Number(tk.v) }
    if (tk.t === 'op') {
      if (tk.v === '(') {
        const e = expr()
        if (!isOp(')')) throw bad
        p++
        return { t: 'group', e }
      }
      throw bad
    }
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          const a = expr()
          if (a.t === 'range') rangesOk++
          args.push(a)
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw bad
        }
      }
      return { t: 'call', name: tk.v.toUpperCase(), args }
    }
    const up = tk.v.toUpperCase()
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') throw bad
      const b = toks[p++].v
      if (isOp('(')) throw bad
      rangesSeen++
      return { t: 'range', a: parseAddr(tk.v), b: parseAddr(b) }
    }
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', a: parseAddr(tk.v) }
  }
  try {
    const e = expr()
    if (p !== toks.length) return null
    return { ast: e, ok: rangesSeen === rangesOk }
  } catch (x) {
    if (x === bad) return null
    throw x
  }
}

// ---- evaluation
const parsed = new Map()
function formulaOf(cell) {
  if (!parsed.has(cell.key)) parsed.set(cell.key, parseFormula(cell.content.slice(1)))
  return parsed.get(cell.key)
}

const memo = new Map()
const active = new Set()
function cellValue(a) {
  if (!a) return err('#REF!')
  const cell = cells.get(a.key)
  if (!cell) return num(0)
  if (memo.has(a.key)) return memo.get(a.key)
  if (active.has(a.key)) return err('#CYCLE!')
  active.add(a.key)
  let v
  const c = cell.content
  if (c[0] === '=') {
    const f = formulaOf(cell)
    v = !f || !f.ok ? err('#ERR!') : ev(f.ast)
  } else if (c === '') v = num(0)
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) v = num(Number(c))
  else if (ERRORS.has(c)) v = err(c)
  else v = { k: 's', v: c }
  active.delete(a.key)
  memo.set(a.key, v)
  return v
}

function toNum(v) {
  if (v.k === 'e') return v
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = { n: 0, s: 1, b: 2 }
function cmpCP(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] - rank[b.k]
  if (a.k === 's') return cmpCP(a.v, b.v)
  return Number(a.v) - Number(b.v)
}

function expand(arg) {
  if (arg.t !== 'range') return [ev(arg)]
  if (!arg.a || !arg.b) return [err('#REF!')]
  const out = []
  const c1 = Math.min(arg.a.col, arg.b.col), c2 = Math.max(arg.a.col, arg.b.col)
  const r1 = Math.min(arg.a.row, arg.b.row), r2 = Math.max(arg.a.row, arg.b.row)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push(cellValue({ col: c, row: r, key: keyOf(c, r) }))
  return out
}

function ev(n) {
  switch (n.t) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'group': return ev(n.e)
    case 'ref': return cellValue(n.a)
    case 'range': return err('#ERR!')
    case 'un': {
      const x = toNum(ev(n.e))
      if (x.k === 'e') return x
      return num(n.op === '-' ? -x.v : x.v)
    }
    case 'bin': {
      const l = ev(n.l), r = ev(n.r)
      if (l.k === 'e') return l
      if (r.k === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const d = compare(l, r)
        const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
        return { k: 'b', v: res }
      }
      const a = toNum(l), b = toNum(r)
      if (a.k === 'e') return a
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        default: return finite(Math.pow(a.v, b.v))
      }
    }
    case 'call': return call(n)
  }
}

function call(n) {
  const { name, args } = n
  const fixed = { ABS: 1, IF: 3 }
  const multi = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
  if (!(name in fixed) && !multi.includes(name)) return err('#NAME?')
  if (name in fixed ? args.length !== fixed[name] : args.length < 1) return err('#ERR!')
  if (name === 'IF') {
    const one = (a) => { const v = expand(a); return v.length === 1 ? v[0] : err('#VALUE!') }
    const c = one(args[0])
    if (c.k === 'e') return c
    let t
    if (c.k === 'b') t = c.v
    else if (c.k === 'n') t = c.v !== 0
    else return err('#VALUE!')
    return one(args[t ? 1 : 2])
  }
  const vals = args.flatMap(expand)
  const e = vals.find((v) => v.k === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  if (name === 'ABS' && vals.length !== 1) return err('#VALUE!')
  const ns = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    ns.push(x.v)
  }
  switch (name) {
    case 'ABS': return num(Math.abs(ns[0]))
    case 'SUM': return finite(ns.reduce((a, b) => a + b, 0))
    case 'AVG': return ns.length ? finite(ns.reduce((a, b) => a + b, 0) / ns.length) : err('#DIV/0!')
    case 'MIN': return num(Math.min(...ns))
    case 'MAX': return num(Math.max(...ns))
  }
}

function show(v) {
  if (v.k === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.k === 'b') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

// ---- deps
function collect(n, set) {
  switch (n.t) {
    case 'ref': if (n.a) set.set(n.a.key, n.a); break
    case 'range':
      if (n.a && n.b) {
        for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
          for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++)
            set.set(keyOf(c, r), { col: c, row: r, key: keyOf(c, r) })
      }
      break
    case 'group': case 'un': collect(n.e, set); break
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'call': n.args.forEach((a) => collect(a, set)); break
  }
}

let out = ''
for (const cell of sorted) {
  if (mode === 'values') {
    out += `${cell.key}=${show(cellValue(cell))}\n`
  } else {
    let line = `${cell.key}:`
    if (cell.content[0] === '=') {
      const f = formulaOf(cell)
      if (f) {
        const set = new Map()
        collect(f.ast, set)
        for (const d of [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)) line += ' ' + d.key
      }
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
